for code,title,sector,rows in CAREERS:
    missions=[]
    for task_title,scenario,fields in rows:
        principle='Operate from the supplied case facts and internal training rules. Separate verified records, unresolved exceptions and authorized decisions. '+fields[-1]['why']
        missions.append(case(task_title,scenario,principle,fields,['Inspect the source record','Apply the checked operating decision','Record the handover and exception status']))
    programme(code,title,'Hands-on '+sector.replace('-',' ')+' records, exception handling, controls and professional handover.',['DB-00'],missions,['records-lab','spreadsheets','communication','evidence'],category='Professional Career')

