    p['skills']=[dict(id=p['id']+'-SK1',title='Inspect and interpret domain records'),dict(id=p['id']+'-SK2',title='Produce and test domain deliverables'),dict(id=p['id']+'-SK3',title='Explain decisions and hand over evidence')]
