content=dict(version='2.0',source='Student Assignment Workspace (3) (1).pdf',stages=STAGES,programmes=P,
             tools=[dict(id=a,name=b,category=c,status=d,limitations=e,configuredUrl=None,privacy='Fictional or explicitly consented data only.',stages=['LEARN','TRY','BUILD','TEST','EVIDENCE']) for a,b,c,d,e in TOOLS],
             products=products,rubric=RUBRIC,lifecycle=['Draft','Submitted','In Review','Request Changes','Resubmitted','Approved','Pending Verification','Verified','Evidence Issued'],
             supportCategories=['Account','Payment','Course','Assessment','Technical','Refund','Accessibility','Appeal'])
ids=[p['id'] for p in P];assert len(ids)==48 and len(set(ids))==48
tool_ids={t[0] for t in TOOLS}
for p in P:
    assert all(k in ids for k in p['prerequisites'])
    assert all(k in tool_ids for k in p['tools'])
    assert p['modules'] and p['assessment']['rubric'] and p['assessment']['evidence']
visited=set();visiting=set()
def walk(pid):
    assert pid not in visiting, 'Circular prerequisite '+pid
    if pid in visited:return
    visiting.add(pid)
    for q in next(p for p in P if p['id']==pid)['prerequisites']:walk(q)
    visiting.remove(pid);visited.add(pid)
for pid in ids:walk(pid)
(ROOT/'dist/curriculum.js').write_text('window.ACADEMY_CONTENT='+json.dumps(content,ensure_ascii=False,separators=(',',':'))+';\n')
(ROOT/'content/curriculum.json').write_text(json.dumps(content,ensure_ascii=False,indent=2))
print(f'{len(P)} programmes / {sum(len(mod["missions"]) for p in P for mod in p["modules"])} missions / 576 lesson units')
